    physical: &mut ReplayPhysicalReservation,
    charge: &mut dyn FnMut(usize) -> Result<(), crate::diagnostic::Diagnostic>,
) -> Result<RenewalBindings<'a>, crate::diagnostic::Diagnostic> {
