//! Complete selected renewal reconstruction with finite inline refusals.
//! The old Diagnostic receiver remains independent in selected.rs.
use super::child_refusal::Refusal;
use super::{HelperSites, RenewalBindings};
use crate::cleanup_plan::{ReplayPhysicalReservation, replay_btree_node_upper};
use crate::hir::{
    ExpressionId, ResolvedBinding, ResolvedExprKind, ResolvedFunction, ResolvedStatement, ValueId,
};
use std::collections::{BTreeMap, BTreeSet};
mod append;
mod cells;
const DEPTH: usize = 514;
type Frame<'a> = Option<(crate::hir::lexical_exit::ChildCursor<'a>, bool, bool)>;
fn error() -> Refusal {
    Refusal::RenewalCensus
}
/// Complete current receiving/refusal controls, not a former-header delta.
fn prepay<T>(
    physical: &mut ReplayPhysicalReservation,
    charge: &mut dyn FnMut(usize) -> Result<(), Refusal>,
) -> Result<(), Refusal> {
    physical
        .reserve(std::mem::size_of::<(
            Refusal,
            Result<T, Refusal>,
            Result<(), Refusal>,
            Result<bool, Refusal>,
            Option<Refusal>,
            BTreeSet<ValueId>,
            BTreeMap<ExpressionId, ExpressionId>,
            BTreeMap<ExpressionId, &ResolvedBinding>,
        )>())
        .map_err(|_| error())?;
    charge(8)
}
pub(crate) fn bindings_with_reservation_and_work_inline<'a>(
    program: &'a dyn crate::cleanup::ReplayContext,
    function: &'a ResolvedFunction,
    physical: &mut ReplayPhysicalReservation,
    charge: &mut dyn FnMut(usize) -> Result<(), Refusal>,
) -> Result<RenewalBindings<'a>, Refusal> {
    prepay::<RenewalBindings<'a>>(physical, charge)?;
    physical
        .reserve(std::mem::size_of::<[Frame<'_>; DEPTH]>())
        .map_err(|_| error())?;
    let mut frames = [None; DEPTH];
    let mut mutable = BTreeSet::new();
    walk(
        function,
        &mut frames,
        charge,
        |statement, _in_loop, charge| {
            if let ResolvedStatement::Let {
                binding,
                mutable: true,
                ..
            } = statement
            {
                charge(
                    (mutable.len() + 1)
                        .checked_mul(binding.id.as_str().len() + 1)
                        .and_then(|n| n.checked_mul(2))
                        .ok_or_else(error)?,
                )?;
                if !mutable.contains(&binding.id) {
                    physical
                        .reserve(replay_btree_node_upper::<ValueId, ()>().ok_or_else(error)?)
                        .map_err(|_| error())?;
                }
                mutable.insert(binding.id.clone());
            }
            Ok(())
        },
    )?;
    let mut legacy = BTreeMap::new();
    let mut appends = BTreeMap::new();
    walk(
        function,
        &mut frames,
        charge,
        |statement, in_loop, charge| {
            if let ResolvedStatement::Assign {
                binding,
                field: None,
                value,
                ..
            } = statement
            {
                charge(
                    (mutable.len() + legacy.len() + 2)
                        .checked_mul(binding.id.as_str().len() + value.id.as_str().len() + 2)
                        .and_then(|n| n.checked_mul(2))
                        .ok_or_else(error)?,
                )?;
                let appended = append::admitted(binding, value, physical, charge)?;
                if appended {
                    if !mutable.contains(&binding.id) {
                        return Err(error());
                    }
                    let ResolvedExprKind::Call { args, .. } = &value.kind else {
                        unreachable!()
                    };
                    charge(
                        (appends.len() + 1)
                            .checked_mul(args[0].id.as_str().len() + 1)
                            .and_then(|n| n.checked_mul(2))
                            .ok_or_else(error)?,
                    )?;
                    if !appends.contains_key(&args[0].id) {
                        physical
                            .reserve(
                                replay_btree_node_upper::<ExpressionId, ExpressionId>()
                                    .ok_or_else(error)?,
                            )
                            .map_err(|_| error())?;
                    }
                    appends.insert(args[0].id.clone(), value.id.clone());
                }
                if mutable.contains(&binding.id)
                    && (crate::byte_ops::is_same_owner_set_hir(value, &binding.id)
                        || (crate::string_ops::replacement::admitted(binding, value) && !appended)
                        || (in_loop && {
                            prepay::<bool>(physical, charge)?;
                            cells::vector(program, binding, value, charge)?
                        }))
                {
                    if !legacy.contains_key(&value.id) {
                        physical
                            .reserve(
                                replay_btree_node_upper::<ExpressionId, &ResolvedBinding>()
                                    .ok_or_else(error)?,
                            )
                            .map_err(|_| error())?;
                    }
                    legacy.insert(value.id.clone(), binding);
                }
            }
            Ok(())
        },
    )?;
    let helpers =
        crate::loop_calls::byte_writer::checked_bindings_with_reservation_and_work_inline(
            program, function, physical, charge,
        )?;
    Ok(RenewalBindings {
        legacy,
        appends,
        helpers: HelperSites::Owned(helpers),
    })
}
fn walk<'a>(
    function: &'a ResolvedFunction,
    frames: &mut [Frame<'a>; DEPTH],
    charge: &mut dyn FnMut(usize) -> Result<(), Refusal>,
    mut statement: impl FnMut(
        &'a ResolvedStatement,
        bool,
        &mut dyn FnMut(usize) -> Result<(), Refusal>,
    ) -> Result<(), Refusal>,
) -> Result<(), Refusal> {
    frames.fill(None);
    frames[0] = Some((
        crate::hir::lexical_exit::ChildCursor::new(&function.body),
        false,
        false,
    ));
    let mut depth = 1;
    while depth != 0 {
        charge(1)?;
        let (cursor, entered, in_loop) = frames[depth - 1].ok_or_else(error)?;
        let expression = cursor.expression();
        if !entered {
            if let ResolvedExprKind::Block { statements, .. }
            | ResolvedExprKind::VecConstructor { statements, .. } = &expression.kind
            {
                charge(statements.len())?;
                for item in statements {
                    statement(item, in_loop, charge)?;
                }
            }
            frames[depth - 1] = Some((cursor, true, in_loop));
            continue;
        }
        if matches!(expression.kind, ResolvedExprKind::Closure { .. }) {
            depth -= 1;
            continue;
        }
        // Block boundaries are prepaid by the entry statement census;
        // the saved cursor never restarts a statement or match prefix.
        let mut cursor = cursor;
        if let Some(child) = cursor.next() {
            if depth == DEPTH {
                return Err(error());
            }
            frames[depth - 1] = Some((cursor, true, in_loop));
            let mut child_loop = in_loop;
            if let Some((
                ResolvedStatement::While {
                    condition, body, ..
                }
                | ResolvedStatement::LexicalWhile {
                    condition, body, ..
                },
                _,
            )) = cursor.last_statement_child()
            {
                if std::ptr::eq(condition.as_ref(), child) {
                    child_loop = false;
                }
                if std::ptr::eq(body.as_ref(), child) {
                    child_loop = crate::hir::iterator_loop::recognize(condition, body).is_none();
                }
            }
            frames[depth] = Some((
                crate::hir::lexical_exit::ChildCursor::new(child),
                false,
                child_loop,
            ));
            depth += 1;
        } else {
            depth -= 1;
        }
    }
    Ok(())
}

//! Exact same-owner String append receiving facts without Debug formatting.
use super::{DEPTH, prepay};
use super::{Refusal, error};
use crate::cleanup_plan::ReplayPhysicalReservation;
use crate::hir::{OwnershipMode, ResolvedType};
use crate::hir::ResolvedBinding;
pub(crate) fn admitted(
    binding: &ResolvedBinding,
    value: &crate::hir::ResolvedExpr,
    physical: &mut ReplayPhysicalReservation,
    charge: &mut dyn FnMut(usize) -> Result<(), Refusal>,
) -> Result<bool, Refusal> {
    prepay::<bool>(physical, charge)?;
    let crate::hir::ResolvedExprKind::Call {
        callee,
        type_arguments,
        instance: None,
        args,
    } = &value.kind
    else {
        return Ok(false);
    };
    if callee.as_str() != crate::string_ops::CONCAT_ID {
        return Ok(false);
    }
    let [left, right] = args.as_slice() else {
        return Err(error());
    };
    if binding.ty != ResolvedType::String
        || binding.ownership != OwnershipMode::Own
        || value.ty != ResolvedType::String
        || value.ownership != OwnershipMode::Own
        || !type_arguments.is_empty()
        || args
            .iter()
            .any(|a| a.ty != ResolvedType::String || a.ownership != OwnershipMode::Own)
    {
        return Err(error());
    }
    let crate::hir::ResolvedExprKind::Place(place) = &left.kind else {
        return Ok(false);
    };
    if place.root != binding.id || !place.projections.is_empty() {
        return Ok(false);
    }
    type Frame<'a> = Option<crate::hir::lexical_exit::ChildCursor<'a>>;
    physical
        .reserve(std::mem::size_of::<[Frame<'_>; DEPTH]>())
        .map_err(|_| error())?;
    let mut frames = [None; DEPTH];
    frames[0] = Some(crate::hir::lexical_exit::ChildCursor::new(right));
    let mut depth = 1;
    while depth != 0 {
        charge(1)?;
        let cursor = frames[depth - 1].as_mut().ok_or_else(error)?;
        if !cursor.is_started() {
            let node = cursor.expression();
            charge(binding.id.as_str().len() + 1)?;
            if matches!(&node.kind,crate::hir::ResolvedExprKind::Place(p) if p.root==binding.id) {
                return Err(error());
            }
        }
        if let Some(child) = cursor.next() {
            if depth == DEPTH {
                return Err(error());
            }
            frames[depth] = Some(crate::hir::lexical_exit::ChildCursor::new(child));
            depth += 1;
        } else {
            frames[depth - 1] = None;
            depth -= 1;
        }
    }
    Ok(true)
}

//! Exact selected ordinary-loop cell facts; no allocated legacy census.
use super::Refusal;
use crate::hir::ResolvedTypeDeclarationKind;
use crate::hir::{OwnershipMode, ResolvedExpr, ResolvedType};
use crate::hir::{ResolvedBinding, ResolvedExprKind};
pub(super) fn vector(
    program: &dyn crate::cleanup::ReplayContext,
    binding: &ResolvedBinding,
    value: &ResolvedExpr,
    charge: &mut dyn FnMut(usize) -> Result<(), Refusal>,
) -> Result<bool, Refusal> {
    let query = match &binding.ty {
        ResolvedType::Nominal { declaration, .. } => declaration.as_str().len(),
        _ => return Ok(false),
    };
    prepay_collection_probes(program, query, charge)?;
    let Ok(Some(element)) = crate::cleanup::selected_vector_element(program, &binding.ty) else {
        return Ok(false);
    };
    let ResolvedExprKind::Call {
        callee,
        instance: None,
        type_arguments,
        args,
    } = &value.kind
    else {
        return Ok(false);
    };
    charge(
        callee
            .as_str()
            .len()
            .min(64)
            .checked_add(1)
            .and_then(|n| n.checked_mul(32))
            .ok_or_else(super::error)?,
    )?;
    charge(
        binding
            .id
            .as_str()
            .len()
            .checked_add(1)
            .and_then(|n| n.checked_mul(4))
            .ok_or_else(super::error)?,
    )?;
    let Some(op) = crate::vec_ops::by_id(callee.as_str()).filter(|op| op.reopens_same_owner())
    else {
        return Ok(false);
    };
    if binding.ownership != OwnershipMode::Own
        || value.ownership != OwnershipMode::Own
        || value.ty != binding.ty
        || type_arguments.as_slice() != std::slice::from_ref(element)
        || args.len() != op.arity()
    {
        return Ok(false);
    }
    if !(crate::vec_ops::resolved_operation_element_is_admitted(op, element)
        || crate::hir::owned_leaf_collection::vec_operation_admitted(
            program.declarations(),
            op,
            element,
        ))
    {
        return Ok(false);
    }
    let owned = *element == ResolvedType::Bytes
        || *element == ResolvedType::String
        || crate::hir::owned_leaf_collection::runtime_element(program.declarations(), element);
    Ok(args.iter().enumerate().all(|(i,arg)|{
        let mode=if owned{op.param_ownership_for(i,element)}else{op.param_ownership(i)};
        let ty=match i {0=>arg.ty==binding.ty,1 if op==crate::vec_ops::VecOp::Push =>&arg.ty==element,2=>&arg.ty==element,_=>arg.ty==ResolvedType::Usize};
        ty&&arg.ownership==mode&&(i!=0||matches!(&arg.kind,ResolvedExprKind::Place(p) if p.root==binding.id&&p.projections.is_empty()))
    }))
}

fn prepay_collection_probes(
    program: &dyn crate::cleanup::ReplayContext,
    query_bytes: usize,
    charge: &mut dyn FnMut(usize) -> Result<(), Refusal>,
) -> Result<(), Refusal> {
    let fail = || Refusal::CollectionProbe;
    if program.type_count() > 32 {
        return Err(fail());
    }
    let mut bytes = query_bytes.checked_add(1).ok_or_else(fail)?;
    for ordinal in 0..program.type_count() {
        charge(1)?;
        let item = program.type_at(ordinal).ok_or_else(fail)?;
        bytes = bytes
            .checked_add(item.id.as_str().len())
            .and_then(|n| n.checked_add(item.name.len() + 1))
            .ok_or_else(fail)?;
        for parameter in &item.type_parameters {
            charge(1)?;
            bytes = bytes
                .checked_add(parameter.name.len() + 1)
                .ok_or_else(fail)?;
        }
        if let ResolvedTypeDeclarationKind::Record { fields } = &item.kind {
            for field in fields {
                charge(1)?;
                bytes = bytes
                    .checked_add(field.id.as_str().len())
                    .and_then(|n| n.checked_add(field.name.len() + 1))
                    .ok_or_else(fail)?;
            }
        }
    }
    // Four root/argument/result Vec classifiers plus operation and ownership
    // classification use fewer than 64 indexed probes per key. The separate
    // 128 factor covers current-directory scans and bounded pairwise fields.
    let probes = program
        .declarations()
        .declarations()
        .len()
        .checked_add(1)
        .and_then(|n| n.checked_mul(64))
        .and_then(|n| n.checked_add(128))
        .ok_or_else(fail)?;
    charge(bytes.checked_mul(probes).ok_or_else(fail)?)
}

