                if first {
                    return Ok(Some(scrutinee));
                }
                if let Some(item) = arms.get(*arm) {
                    if *guard {
                        *guard = false;
                        if let Some(value) = &item.guard {
                            return Ok(Some(value));
                        }
                    }
                    *arm += 1;
                    *guard = true;
                    return Ok(Some(&item.value));
